    11	/** The due figures of claims and the due-total of a person's claims. */
    12	public final class Dues {
    13	
    14	    private Dues() {
    15	    }
    16	
    17	    /**
    18	     * A claim's due: once settled, the due fixed then (its late charge frozen in); otherwise its
    19	     * {@link #base} figure plus, while overdue, its {@link RateTable#lateCharge late charge}. Null when there
    20	     * is none.
    21	     */
    22	    public static BigDecimal figure(Claim claim, Grades grades, RateTable rates) {
    23	        if (claim.getSettledDue() != null) {
    24	            return claim.getSettledDue();
    25	        }
    26	        BigDecimal base = base(claim, grades, rates);
    27	        if (base == null || claim.isCorrection() || !overdue(claim, rates)) {
    28	            return base;
    29	        }
    30	        return base.add(rates.lateCharge(base, claim.getDate(), claim.getDueBy(), claim.getRoundsBy()));
    31	    }
    32	
    33	    /**
    34	     * A claim's figure before any late charge: while bound by a statement (and not PENDING, which is
    35	     * never bound), the figure bound then;
    36	     * otherwise the amount at the rate in force on its date for its person's grade in force then, but at
    37	     * least the sheet's floor; a correction has no floor and no late charge. Rounded by the date the claim's
    38	     * rounding goes by, see {@link RateTable#rounding}. Null when there is none. A
    39	     * statement binds this figure, never the late charge.
    40	     */
    41	    public static BigDecimal base(Claim claim, Grades grades, RateTable rates) {
    42	        if (bound(claim)) {
    43	            return claim.getStatedDue();
    44	        }
    45	        String grade = grades.on(claim.getDate());
    46	        return claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()),
    47	                rates.rounding(claim.getRoundsBy()))
    48	                : rates.due(claim.getAmount(), grade, claim.getDate());
    49	    }
    50	
    51	    /**
    52	     * The figure the claim would have today as an OPEN claim bound by no statement: the amount at the rate
    53	     * in force on its date for its person's grade then (at least the sheet's floor, a correction having none),
    54	     * plus the late charge it has today when its due-by has passed (a correction having none). Null when
    55	     * there is none. Re-settling a claim fixes its due at this figure.
    56	     */
    57	    public static BigDecimal asOpen(Claim claim, Grades grades, RateTable rates) {
    58	        String grade = grades.on(claim.getDate());
    59	        BigDecimal base = claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()),
    60	                rates.rounding(claim.getRoundsBy()))
    61	                : rates.due(claim.getAmount(), grade, claim.getDate());
    62	        if (base == null || claim.isCorrection() || !claim.getDueBy().isBefore(rates.today())) {
    63	            return base;
    64	        }
    65	        return base.add(rates.lateCharge(base, claim.getDate(), claim.getDueBy(), claim.getRoundsBy()));
    66	    }
    67	
    68	    /** Whether a statement binds the claim's figure: it is stated and not PENDING. */
    69	    public static boolean bound(Claim claim) {
    70	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    71	    }
    72	
    73	    /**
    74	     * Whether the claim is overdue: OPEN or PENDING, not {@link #deferred deferred}, and due by a date before
    75	     * the sheet's today (its due-by, fixed when it was added).
    76	     */
    77	    public static boolean overdue(Claim claim, RateTable rates) {
    78	        return claim.getStatus().unpaid() && !deferred(claim, rates.today()) && claim.getDueBy().isBefore(rates.today());
    79	    }
    80	
    81	    /** Whether the claim is deferred on the given today: OPEN and deferred until a date after it. */
    82	    public static boolean deferred(Claim claim, LocalDate today) {
    83	        return claim.getStatus() == ClaimStatus.OPEN && claim.getDeferredUntil() != null
    84	                && today.isBefore(claim.getDeferredUntil());
    85	    }
    86	
    87	    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
    88	    public static List<Claim> overdue(List<Claim> claims, RateTable rates, Holds holds) {
    89	        return claims.stream().filter(c -> counts(c, holds, rates.today()) && overdue(c, rates)).toList();
    90	    }
    91	
    92	    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
    93	    public static BigDecimal sum(Grades grades, List<Claim> claims, RateTable rates) {
    94	        return claims.stream().map(c -> figure(c, grades, rates)).filter(Objects::nonNull)
    95	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    96	    }
    97	
    98	    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
    99	    private static boolean kept(Claim claim) {
   100	        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
   101	    }
   102	
   103	    /**
   104	     * Whether the claim counts in the live totals on the sheet's today: OPEN, PENDING and SETTLED claims do,
   105	     * except that an OPEN claim dated within one of its person's holds counts in none, unless a statement
   106	     * binds it, and a claim {@link #deferred deferred} on that today counts in none.
   107	     */
   108	    public static boolean counts(Claim claim, Holds holds, LocalDate today) {
   109	        return claim.getStatus().counts() && !deferred(claim, today) && !(claim.getStatus() == ClaimStatus.OPEN
   110	                && !bound(claim) && holds.on(claim.getDate()));
   111	    }
   112	
   113	    /**
   114	     * A person's due-total (see {@link #total}); a person not on hold.
   115	     */
   116	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates) {
   117	        return total(grades, claims, rates, Holds.NONE);
   118	    }
   119	
   120	    /**
   121	     * A person's due-total: their {@link #uncapped} sum held to the sheet's cap, see {@link RateTable#capped}.
   122	     * Null (n/a) when the sum is.
   123	     */
   124	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
   125	        return rates.capped(uncapped(grades, claims, rates, holds));
   126	    }
   127	
   128	    /** What a person's {@link #uncapped} sum is above the sheet's cap: 0.00 when it is not, or is n/a. */
   129	    public static BigDecimal excess(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
   130	        return rates.excess(uncapped(grades, claims, rates, holds));
   131	    }
   132	
   133	    /**
   134	     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a)
   135	     * when the grade in force on the sheet's today has no rate on it, unless a claim that counts has a
   136	     * figure not made by that grade (kept, or at the rate for another grade in force on its date): then it
   137	     * is the sum of the figures there are; so too when that grade's rate has ended by the sheet's today and
   138	     * a claim that counts has a figure.
   139	     */
   140	    public static BigDecimal uncapped(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
   141	        List<Claim> counting = claims.stream().filter(c -> counts(c, holds, rates.today())).toList();
   142	        String current = grades.on(rates.today());
   143	        boolean ended = rates.ended(current, rates.today());
   144	        boolean shown = rates.current(current) != null || counting.stream().anyMatch(c -> kept(c)
   145	                || ((ended || !current.equals(grades.on(c.getDate()))) && figure(c, grades, rates) != null));
   146	        return shown ? counting.stream().map(c -> figure(c, grades, rates))
   147	                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
   148	    }
   149	}
