    88	    @Transactional
    89	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
    90	            String corrects) {
    91	        Person person = people.findByIdAndSheetId(personId, sheetId)
    92	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    93	        LocalDate on = date != null ? date : sheets.today(sheetId);
    94	        periods.requireOpen(sheetId, on);
    95	        requireNotRetired(person, on);
    96	        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects);
    97	        Rollup.Figures before = rollup.figures(sheetId);
    98	        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
    99	        claim.setCorrectsDate(correctsDate);
   100	        sheets.load(sheetId, user);
   101	        claim.setDueBy(on.plusDays(sheets.settings(sheetId).termsFor(person.gradeOn(on), on)));
   102	        log(sheetId, user, claim, person);
   103	        claims.saveAndFlush(claim);
   104	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null));
   105	        rollup.changed(sheetId, user, before);
   106	        return personId;
