   167	            claim.setOpenedBy(user);
   168	        }
   169	        String number = claim.getShownNumber();
   170	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
   171	        String due = null;
   172	        if (next == ClaimStatus.SETTLED) {
   173	            BigDecimal fixed = dueNow(sheetId, claim, owner);
   174	            if (access.canSettle(sheetId, user, fixed)) {
   175	                claim.setSettledDue(fixed);
   176	                due = fixed == null ? "n/a" : fixed.toPlainString();
