    16	/**
    17	 * Paste claims: lines of {@code name,amount,date,note} (the note may hold commas and may be left out; a
    18	 * blank date takes the sheet's today), each a DRAFT claim for the person of that name on the sheet,
    19	 * matched as the person form matches names. Every line is held to the claim form's rules and the whole
    20	 * paste is one change: a refused line adds nothing.
    21	 */
    22	@Service
    23	public class PasteClaimsService {
    24	
    25	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,12}(\\.\\d{1,2})?");
    26	    private static final int NOTE_MAX = 500;
    27	
    28	    private record Line(Person person, BigDecimal amount, LocalDate date, String note) {
    29	    }
    30	
    31	    private final PersonRepository people;
    32	    private final ClaimService claims;
    33	
    34	    public PasteClaimsService(PersonRepository people, ClaimService claims) {
    35	        this.people = people;
    36	        this.claims = claims;
    37	    }
    38	
    39	    /** Add a claim per line, in order; returns how many were added. */
    40	    @Transactional
    41	    public int paste(String sheetId, String user, String text) {
    42	        List<Line> lines = new ArrayList<>();
    43	        for (String raw : text.split("\\R")) {
    44	            if (!raw.isBlank()) lines.add(parse(sheetId, raw));
    45	        }
    46	        if (lines.isEmpty()) {
    47	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Paste at least one line");
    48	        }
    49	        for (Line line : lines) {
    50	            claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note());
    51	        }
    52	        return lines.size();
    53	    }
    54	
    55	    private Line parse(String sheetId, String raw) {
    56	        String[] f = raw.split(",", 4);
    57	        if (f.length < 2) throw refused(raw, "give a name and an amount");
    58	        String name = f[0].trim();
    59	        Person person = name.isEmpty() ? null
    60	                : people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
    61	        if (person == null) throw refused(raw, "no one named \"" + name + "\" is on the sheet");
    62	        String amount = f[1].trim();
    63	        if (!AMOUNT.matcher(amount).matches()) throw refused(raw, "the amount must have up to two decimals");
    64	        LocalDate date = null;
    65	        if (f.length > 2 && !f[2].isBlank()) {
    66	            try {
    67	                date = LocalDate.parse(f[2].trim());
    68	            } catch (DateTimeParseException e) {
    69	                throw refused(raw, "the date must be YYYY-MM-DD");
    70	            }
    71	        }
    72	        String note = f.length > 3 ? f[3].trim() : "";
    73	        if (note.length() > NOTE_MAX) throw refused(raw, "the note is too long");
    74	        return new Line(person, new BigDecimal(amount), date, note);
    75	    }
    76	
    77	    private static ResponseStatusException refused(String line, String why) {
    78	        return new ResponseStatusException(HttpStatus.CONFLICT, "Line \"" + line + "\": " + why);
    79	    }
    80	}
