    27	    /** The selected claims on the sheet, in list order; an id not on the sheet is left out. */
    28	    public List<Claim> inListOrder(String sheetId, Set<Long> claimIds) {
    29	        Map<Long, Integer> personOrder = new HashMap<>();
    30	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
    31	        for (int i = 0; i < listed.size(); i++) {
    32	            personOrder.put(listed.get(i).getId(), i);
    33	        }
    34	        return claimRows.findBySheetIdOrderByListedDesc(sheetId).stream()
    35	                .filter(c -> claimIds.contains(c.getId()))
    36	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
    37	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
    38	                .toList();
    39	    }
