546	   109	    /**
547	   110	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
548	   111	     * added again instead), and an edit is refused when a closed period contains its date or the new one.
549	   112	     * Returns the person it belongs to.
550	   113	     */
551	   114	    @Transactional
552	   115	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
553	   116	            String corrects) {
554	   117	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
555	   118	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
556	   119	        LocalDate on = date != null ? date : sheets.today(sheetId);
557	   120	        periods.requireOpen(sheetId, claim.getDate(), on);
558	   121	        if (claim.getStatus() != ClaimStatus.DRAFT) {
559	   122	            throw new ResponseStatusException(HttpStatus.CONFLICT,
560	   123	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
561	   124	        }
562	   125	        if (!on.equals(claim.getDate())) {
563	   126	            people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
564	   127	        }
565	   128	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
566	   129	        Rollup.Figures before = rollup.figures(sheetId);
567	   130	        claim.setAmount(amount);
568	   131	        claim.setCorrects(corrects);
569	   132	        claim.setCorrectsDate(correctsDate);
570	   133	        claim.setDate(on);
571	   134	        claim.setNote(note == null ? "" : note);
572	   135	        claims.flush();
573	   136	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
574	   137	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
575	   138	                claim.getDate(), claim.getShownNumber(), null));
576	   139	        rollup.changed(sheetId, user, before);
577	   140	        return claim.getPersonId();
578	   141	    }
