580	   143	    /**
581	   144	     * Move a claim to a status; a move its status does not allow, settling by the user who opened
582	   145	     * the claim, or moving a claim dated inside a closed period, is refused and changes nothing. Settling
583	   146	     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
584	   147	     * Returns the person it belongs to.
585	   148	     */
586	   149	    @Transactional
587	   150	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
588	   151	        Claim claim = claim(sheetId, claimId);
589	   152	        if (!claim.getStatus().canBecome(next)) {
590	   153	            throw new ResponseStatusException(HttpStatus.CONFLICT,
591	   154	                    "A " + claim.getStatus() + " claim cannot become " + next);
592	   155	        }
593	   156	        if (next == ClaimStatus.SETTLED && Dues.deferred(claim, sheets.today(sheetId))) {
594	   157	            throw new ResponseStatusException(HttpStatus.CONFLICT,
595	   158	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then");
596	   159	        }
597	   160	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
598	   161	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
599	   162	                    "The user who opened a claim cannot settle it");
600	   163	        }
601	   164	        Rollup.Figures before = rollup.figures(sheetId);
602	   165	        if (next == ClaimStatus.OPEN) {
603	   166	            giveNumber(sheetId, claim);
604	   167	            claim.setOpenedBy(user);
605	   168	        }
606	   169	        String number = claim.getShownNumber();
607	   170	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
608	   171	        String due = null;
609	   172	        if (next == ClaimStatus.SETTLED) {
610	   173	            BigDecimal fixed = dueNow(sheetId, claim, owner);
611	   174	            if (access.canSettle(sheetId, user, fixed)) {
612	   175	                claim.setSettledDue(fixed);
613	   176	                due = fixed == null ? "n/a" : fixed.toPlainString();
614	   177	            } else {
615	   178	                next = ClaimStatus.PENDING;
616	   179	            }
617	   180	        }
618	   181	        claim.setStatus(next);
619	   182	        log(sheetId, user, claim, owner);
620	   183	        claims.flush();
621	   184	        String person = owner == null ? "" : owner.getName();
622	   185	        String event = switch (next) {
623	   186	            case OPEN -> "CLAIM_OPENED";
624	   187	            case PENDING -> "CLAIM_PENDING";
625	   188	            case SETTLED -> "CLAIM_SETTLED";
626	   189	            case VOID -> "CLAIM_VOIDED";
627	   190	            case DRAFT -> throw new IllegalStateException();
628	   191	        };
629	   192	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
630	   193	        rollup.changed(sheetId, user, before);
631	   194	        return claim.getPersonId();
632	   195	    }
