634	   197	    /**
635	   198	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
636	   199	     * counts in no total, is not overdue, cannot be settled and no statement binds it (see
637	   200	     * {@link Dues#deferred}). A claim not OPEN, a date not after today, or a claim dated inside a closed
638	   201	     * period is refused and nothing changes. Returns the person it belongs to.
639	   202	     */
640	   203	    @Transactional
641	   204	    public long defer(String sheetId, String user, long claimId, LocalDate until) {
642	   205	        Claim claim = claim(sheetId, claimId);
643	   206	        if (claim.getStatus() != ClaimStatus.OPEN) {
644	   207	            throw new ResponseStatusException(HttpStatus.CONFLICT,
645	   208	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
646	   209	        }
647	   210	        LocalDate today = sheets.today(sheetId);
648	   211	        if (!until.isAfter(today)) {
649	   212	            throw new ResponseStatusException(HttpStatus.CONFLICT,
650	   213	                    "A claim can only be deferred to a date after the sheet's today (" + today + ")");
651	   214	        }
652	   215	        Rollup.Figures before = rollup.figures(sheetId);
653	   216	        claim.setDeferredUntil(until);
654	   217	        claims.flush();
655	   218	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
656	   219	        events.publishEvent(new ClaimDeferred(sheetId, user, person, claim.getAmount(), claim.getDate(),
657	   220	                claim.getShownNumber(), until));
658	   221	        rollup.changed(sheetId, user, before);
659	   222	        return claim.getPersonId();
660	   223	    }
