662	   225	    /**
663	   226	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
664	   227	     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
665	   228	     * closed period is refused and nothing changes. Returns the person it belongs to.
666	   229	     */
667	   230	    @Transactional
668	   231	    public long approve(String sheetId, String user, long claimId) {
669	   232	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
670	   233	        if (user.equals(claim.getOpenedBy())) {
671	   234	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
672	   235	        }
673	   236	        Rollup.Figures before = rollup.figures(sheetId);
674	   237	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
675	   238	        BigDecimal fixed = dueNow(sheetId, claim, owner);
676	   239	        claim.setSettledDue(fixed);
677	   240	        claim.setStatus(ClaimStatus.SETTLED);
678	   241	        log(sheetId, user, claim, owner);
679	   242	        claims.flush();
680	   243	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
681	   244	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
682	   245	        rollup.changed(sheetId, user, before);
683	   246	        return claim.getPersonId();
684	   247	    }
