686	   249	    /**
687	   250	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
688	   251	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
689	   252	     * steward re-settles; a claim not SETTLED or dated inside a closed period is refused and nothing changes.
690	   253	     * Returns the person it belongs to.
691	   254	     */
692	   255	    @Transactional
693	   256	    public long resettle(String sheetId, String user, long claimId) {
694	   257	        Claim claim = claim(sheetId, claimId);
695	   258	        if (claim.getStatus() != ClaimStatus.SETTLED) {
696	   259	            throw new ResponseStatusException(HttpStatus.CONFLICT,
697	   260	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
698	   261	        }
699	   262	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
700	   263	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
701	   264	        }
702	   265	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
703	   266	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
704	   267	        Rollup.Figures before = rollup.figures(sheetId);
705	   268	        BigDecimal old = claim.getSettledDue();
706	   269	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
707	   270	        claim.setSettledDue(fixed);
708	   271	        claim.logStatus(user, sheets.today(sheetId), fixed);
709	   272	        claims.flush();
710	   273	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
711	   274	                claim.getShownNumber(), old, fixed));
712	   275	        rollup.changed(sheetId, user, before);
713	   276	        return claim.getPersonId();
714	   277	    }
