716	   279	    /**
717	   280	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
718	   281	     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
719	   282	     * period is refused and nothing changes. Returns the person it belongs to.
720	   283	     */
721	   284	    @Transactional
722	   285	    public long reject(String sheetId, String user, long claimId, String reason) {
723	   286	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
724	   287	        Rollup.Figures before = rollup.figures(sheetId);
725	   288	        claim.setStatus(ClaimStatus.OPEN);
726	   289	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
727	   290	        log(sheetId, user, claim, owner);
728	   291	        claims.flush();
729	   292	        String person = owner == null ? "" : owner.getName();
730	   293	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
731	   294	                claim.getDate(), claim.getShownNumber(), null, reason));
732	   295	        rollup.changed(sheetId, user, before);
733	   296	        return claim.getPersonId();
734	   297	    }
