736	   299	    /**
737	   300	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
738	   301	     * number and date, is released from any figure a statement bound it to (live again until its new
739	   302	     * person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
740	   303	     * correction, a claim dated inside a closed period or after the new person's retirement date, or a move
741	   304	     * by anyone but a steward is refused and nothing changes. Returns the people it moved from and to.
742	   305	     */
743	   306	    @Transactional
744	   307	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
745	   308	        Claim claim = claim(sheetId, claimId);
746	   309	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
747	   310	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can reassign a claim");
748	   311	        }
749	   312	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
750	   313	                && claim.getStatus() != ClaimStatus.PENDING) {
751	   314	            throw new ResponseStatusException(HttpStatus.CONFLICT,
752	   315	                    "A " + claim.getStatus() + " claim cannot be reassigned");
753	   316	        }
754	   317	        if (claim.isCorrection()) {
755	   318	            throw new ResponseStatusException(HttpStatus.CONFLICT,
756	   319	                    "A correction belongs with the claim it corrects and cannot be reassigned");
757	   320	        }
758	   321	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
759	   322	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
760	   323	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
761	   324	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
762	   325	        if (from.getId().equals(to.getId())) {
763	   326	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
764	   327	        }
765	   328	        requireNotRetired(to, claim.getDate());
766	   329	        Rollup.Figures before = rollup.figures(sheetId);
767	   330	        claim.setPersonId(to.getId());
768	   331	        claim.unbind();
769	   332	        claims.flush();
770	   333	        claims.relist(claim.getId());
771	   334	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
772	   335	                claim.getShownNumber(), from.getName(), to.getName()));
773	   336	        rollup.changed(sheetId, user, before);
774	   337	        return new long[] { from.getId(), to.getId() };
775	   338	    }
