777	   340	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
778	   341	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
779	   342	        Claim claim = claim(sheetId, claimId);
780	   343	        if (claim.getStatus() != ClaimStatus.PENDING) {
781	   344	            throw new ResponseStatusException(HttpStatus.CONFLICT,
782	   345	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
783	   346	        }
784	   347	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
785	   348	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
786	   349	        }
787	   350	        return claim;
