790	   353	    private Claim claim(String sheetId, long claimId) {
791	   354	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
792	   355	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
793	   356	        periods.requireOpen(sheetId, claim.getDate());
794	   357	        return claim;
