797	   360	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
798	   361	    private void log(String sheetId, String user, Claim claim, Person owner) {
799	   362	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
800	   363	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
801	   364	        claim.logStatus(user, sheets.today(sheetId), due);
802	   365	    }
803	   366	
804	   367	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
805	   368	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
806	   369	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
807	   370	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
808	   371	    }
