810	   373	    /**
811	   374	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
812	   375	     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
813	   376	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
814	   377	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
815	   378	     */
816	   379	    private void giveNumber(String sheetId, Claim claim) {
817	   380	        LocalDate from = sheets.periodNumberingFrom(sheetId);
818	   381	        if (from == null || sheets.today(sheetId).isBefore(from)) {
819	   382	            claim.setNumber(sheets.nextClaimNumber(sheetId));
820	   383	            return;
821	   384	        }
822	   385	        sheetRows.lockById(sheetId);
823	   386	        Period period = periods.list(sheetId).stream().filter(p -> p.contains(claim.getDate()))
824	   387	                .findFirst().orElse(null);
825	   388	        String sequence = period == null ? "X" : "P" + period.getId();
826	   389	        int n = claims.lastInSequence(sheetId, sequence) + 1;
827	   390	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
828	   391	    }
829	   392	
830	   393	    /**
831	   394	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
832	   395	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
833	   396	     * correction corrects (its rounding goes by it); null for any other claim.
834	   397	     */
835	   398	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
836	   399	        if (amount.signum() >= 0) {
837	   400	            if (corrects != null) {
838	   401	                throw new ResponseStatusException(HttpStatus.CONFLICT,
839	   402	                        "Only a correction (a negative amount) names a claim it corrects");
840	   403	            }
841	   404	            return null;
842	   405	        }
843	   406	        if (corrects == null) {
844	   407	            throw new ResponseStatusException(HttpStatus.CONFLICT,
845	   408	                    "A negative amount is a correction; name the number of the settled claim it corrects");
846	   409	        }
847	   410	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
848	   411	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
849	   412	                .map(Claim::getDate).findFirst()
850	   413	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
851	   414	                        "Claim " + corrects + " is not a settled claim of this person"));
852	   415	    }
853	   416	
854	   417	    /** Refuse a claim dated after its person's retirement date. */
855	   418	    private static void requireNotRetired(Person person, LocalDate date) {
856	   419	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
857	   420	            throw new ResponseStatusException(HttpStatus.CONFLICT,
858	   421	                    person.getName() + " is retired from " + person.getRetiredFrom()
859	   422	                            + "; a claim cannot be dated after that");
860	   423	        }
861	   424	    }
862	   425	}
