     3	/**
     4	 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling
     5	 * one above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (back to
     6	 * OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). Only OPEN, PENDING and SETTLED claims count
     7	 * toward what is claimed.
     8	 */
     9	public enum ClaimStatus {
    10	    DRAFT, OPEN, PENDING, SETTLED, VOID;
    11	
    12	    /** Whether the claim counts toward claimed, due-total and every total. */
    13	    public boolean counts() {
    14	        return this == OPEN || this == PENDING || this == SETTLED;
    15	    }
    16	
    17	    /** Whether the claim is still to be paid: OPEN or PENDING. */
    18	    public boolean unpaid() {
    19	        return this == OPEN || this == PENDING;
    20	    }
    21	
    22	    /**
    23	     * Whether a claim in this status may be moved to the given one by opening, settling or voiding it; a
    24	     * PENDING claim leaves PENDING only by being approved, rejected or voided.
    25	     */
    26	    public boolean canBecome(ClaimStatus next) {
    27	        return switch (next) {
    28	            case OPEN -> this == DRAFT;
    29	            case PENDING, SETTLED -> this == OPEN;
    30	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
    31	            case DRAFT -> false;
    32	        };
    33	    }
    34	}
