   228	     * closed period is refused and nothing changes. Returns the person it belongs to.
   229	     */
   230	    @Transactional
   231	    public long approve(String sheetId, String user, long claimId) {
   232	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
   233	        if (user.equals(claim.getOpenedBy())) {
   234	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
   235	        }
   236	        Rollup.Figures before = rollup.figures(sheetId);
   237	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
   238	        BigDecimal fixed = dueNow(sheetId, claim, owner);
   239	        claim.setSettledDue(fixed);
   240	        claim.setStatus(ClaimStatus.SETTLED);
   241	        log(sheetId, user, claim, owner);
   242	        claims.flush();
   243	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
   244	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
   245	        rollup.changed(sheetId, user, before);
   246	        return claim.getPersonId();
   247	    }
   248	
   249	    /**
   250	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
   251	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
   252	     * steward re-settles; a claim not SETTLED or dated inside a closed period is refused and nothing changes.
   253	     * Returns the person it belongs to.
   254	     */
   255	    @Transactional
   256	    public long resettle(String sheetId, String user, long claimId) {
   257	        Claim claim = claim(sheetId, claimId);
   258	        if (claim.getStatus() != ClaimStatus.SETTLED) {
   259	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   260	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
   261	        }
   262	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
   263	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
   264	        }
   265	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
   266	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
   267	        Rollup.Figures before = rollup.figures(sheetId);
   268	        BigDecimal old = claim.getSettledDue();
   269	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
   270	        claim.setSettledDue(fixed);
   271	        claim.logStatus(user, sheets.today(sheetId), fixed);
   272	        claims.flush();
   273	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
   274	                claim.getShownNumber(), old, fixed));
   275	        rollup.changed(sheetId, user, before);
   276	        return claim.getPersonId();
   277	    }
   278	
   279	    /**
   280	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
   281	     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
   282	     * period is refused and nothing changes. Returns the person it belongs to.
   283	     */
   284	    @Transactional
   285	    public long reject(String sheetId, String user, long claimId, String reason) {
   286	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
   287	        Rollup.Figures before = rollup.figures(sheetId);
   288	        claim.setStatus(ClaimStatus.OPEN);
   289	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
   290	        log(sheetId, user, claim, owner);
   291	        claims.flush();
   292	        String person = owner == null ? "" : owner.getName();
   293	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
   294	                claim.getDate(), claim.getShownNumber(), null, reason));
   295	        rollup.changed(sheetId, user, before);
   296	        return claim.getPersonId();
   297	    }
   298	
   299	    /**
   300	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
   301	     * number and date, is released from any figure a statement bound it to (live again until its new
   302	     * person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
   303	     * correction, a claim dated inside a closed period or after the new person's retirement date, or a move
   304	     * by anyone but a steward is refused and nothing changes. Returns the people it moved from and to.
   305	     */
   306	    @Transactional
   307	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
   308	        Claim claim = claim(sheetId, claimId);
   309	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
   310	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can reassign a claim");
   311	        }
   312	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
   313	                && claim.getStatus() != ClaimStatus.PENDING) {
   314	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   315	                    "A " + claim.getStatus() + " claim cannot be reassigned");
   316	        }
   317	        if (claim.isCorrection()) {
   318	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   319	                    "A correction belongs with the claim it corrects and cannot be reassigned");
   320	        }
   321	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
   322	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
   323	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
   324	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
   325	        if (from.getId().equals(to.getId())) {
   326	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
   327	        }
   328	        requireNotRetired(to, claim.getDate());
   329	        Rollup.Figures before = rollup.figures(sheetId);
   330	        claim.setPersonId(to.getId());
   331	        claim.unbind();
   332	        claims.flush();
   333	        claims.relist(claim.getId());
   334	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
   335	                claim.getShownNumber(), from.getName(), to.getName()));
   336	        rollup.changed(sheetId, user, before);
   337	        return new long[] { from.getId(), to.getId() };
   338	    }
   339	
   340	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
   341	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
   342	        Claim claim = claim(sheetId, claimId);
   343	        if (claim.getStatus() != ClaimStatus.PENDING) {
   344	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   345	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
   346	        }
   347	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
   348	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
   349	        }
   350	        return claim;
   351	    }
   352	
   353	    private Claim claim(String sheetId, long claimId) {
   354	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
   355	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
   356	        periods.requireOpen(sheetId, claim.getDate());
   357	        return claim;
   358	    }
   359	
   360	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
   361	    private void log(String sheetId, String user, Claim claim, Person owner) {
   362	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
   363	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
   364	        claim.logStatus(user, sheets.today(sheetId), due);
   365	    }
   366	
   367	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
   368	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
   369	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
   370	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
   371	    }
   372	
   373	    /**
   374	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
   375	     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
   376	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
   377	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
   378	     */
   379	    private void giveNumber(String sheetId, Claim claim) {
   380	        LocalDate from = sheets.periodNumberingFrom(sheetId);
   381	        if (from == null || sheets.today(sheetId).isBefore(from)) {
   382	            claim.setNumber(sheets.nextClaimNumber(sheetId));
   383	            return;
   384	        }
   385	        sheetRows.lockById(sheetId);
   386	        Period period = periods.list(sheetId).stream().filter(p -> p.contains(claim.getDate()))
   387	                .findFirst().orElse(null);
   388	        String sequence = period == null ? "X" : "P" + period.getId();
   389	        int n = claims.lastInSequence(sheetId, sequence) + 1;
   390	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
   391	    }
   392	
   393	    /**
   394	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
   395	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
   396	     * correction corrects (its rounding goes by it); null for any other claim.
   397	     */
   398	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
   399	        if (amount.signum() >= 0) {
   400	            if (corrects != null) {
   401	                throw new ResponseStatusException(HttpStatus.CONFLICT,
   402	                        "Only a correction (a negative amount) names a claim it corrects");
   403	            }
   404	            return null;
   405	        }
   406	        if (corrects == null) {
   407	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   408	                    "A negative amount is a correction; name the number of the settled claim it corrects");
   409	        }
   410	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
   411	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
   412	                .map(Claim::getDate).findFirst()
   413	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
   414	                        "Claim " + corrects + " is not a settled claim of this person"));
   415	    }
   416	
   417	    /** Refuse a claim dated after its person's retirement date. */
   418	    private static void requireNotRetired(Person person, LocalDate date) {
   419	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
   420	            throw new ResponseStatusException(HttpStatus.CONFLICT,
   421	                    person.getName() + " is retired from " + person.getRetiredFrom()
   422	                            + "; a claim cannot be dated after that");
   423	        }
   424	    }
   425	}

