    12	/**
    13	 * Every rate on a sheet, the sheet's today, its dated settings (the floor and late percent in force on a
    14	 * claim's date, the cap in force on the sheet's today) and its policy date (null: the sheet's today): which rate is in force for a grade on a date, the live due it
    15	 * makes of an amount, the late charge an overdue figure gains, how a claim's figures round, and the most a
    16	 * person's due-total comes to.
    17	 */
    18	public record RateTable(List<Rate> rates, LocalDate today, DatedSettings settings, LocalDate policyDate) {
    19	
    20	    /** The days in each period overdue that adds the late percent once more. */
    21	    private static final int LATE_PERIOD_DAYS = 30;
    22	
    23	    /**
    24	     * The percent in force for the grade on the date: the rate whose from-date is the latest one on
    25	     * or before it, a rate with no from-date applying from the beginning of time; null when none does,
    26	     * or when that rate's to-date is before the date (it has ended, and no later rate is in force).
    27	     */
    28	    public BigDecimal on(String grade, LocalDate date) {
    29	        return latest(grade, date).filter(r -> !ended(r, date)).map(Rate::getPct).orElse(null);
    30	    }
    31	
    32	    /** Whether the grade has no rate on the date only because the rate that would apply has ended by then. */
    33	    public boolean ended(String grade, LocalDate date) {
    34	        return latest(grade, date).filter(r -> ended(r, date)).isPresent();
    35	    }
    36	
    37	    /** The grade's rate with the latest from-date on or before the date, ended or not. */
    38	    private Optional<Rate> latest(String grade, LocalDate date) {
    39	        return rates.stream()
    40	                .filter(r -> r.getGrade().equals(grade))
    41	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
    42	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
    43	    }
    44	
    45	    private static boolean ended(Rate rate, LocalDate date) {
    46	        return rate.getToDate() != null && rate.getToDate().isBefore(date);
    47	    }
    48	
    49	    /** The cap in force on the sheet's today: the most a person's due-total comes to; null when there is none. */
    50	    public BigDecimal cap() {
    51	        return settings.cap(today);
    52	    }
    53	
    54	    /** A due-total held to the cap: the cap when the sum is above it; as it is otherwise, or when n/a (null). */
    55	    public BigDecimal capped(BigDecimal sum) {
    56	        BigDecimal cap = cap();
    57	        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? sum : cap;
    58	    }
    59	
    60	    /** What a due-total's sum is above the cap: 0.00 when it is not, or when n/a (null). */
    61	    public BigDecimal excess(BigDecimal sum) {
    62	        BigDecimal cap = cap();
    63	        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? BigDecimal.ZERO : sum.subtract(cap);
    64	    }
    65	
    66	    /** The percent in force for the grade on the sheet's today; null when none is. */
    67	    public BigDecimal current(String grade) {
    68	        return on(grade, today);
    69	    }
    70	
    71	    /**
    72	     * How the figures of a claim whose rounding goes by the date round: half up when it is before the
    73	     * policy date (the sheet's today when none is set), half to even on or after it.
    74	     */
    75	    public RoundingMode rounding(LocalDate roundsBy) {
    76	        LocalDate policy = policyDate == null ? today : policyDate;
    77	        return roundsBy.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    78	    }
    79	
    80	    /**
    81	     * The live due of an amount dated on the date for the grade: the amount at the rate in force then,
    82	     * rounded by the date, but at least the floor in force on the date; null when no rate is.
    83	     */
    84	    public BigDecimal due(BigDecimal amount, String grade, LocalDate date) {
    85	        BigDecimal due = RateService.due(amount, on(grade, date), rounding(date));
    86	        BigDecimal floor = settings.floor(date);
    87	        return due == null || floor == null || due.compareTo(floor) >= 0 ? due : floor;
    88	    }
    89	
    90	    /**
    91	     * The late charge on a figure of a claim dated on the date and due by the due-by: the late percent in
    92	     * force on its date of the figure for every full 30 days from its due-by to the sheet's today, rounded by
    93	     * the date its claim's rounding goes by; 0.00 when not a full 30 days overdue.
    94	     */
    95	    public BigDecimal lateCharge(BigDecimal figure, LocalDate date, LocalDate dueBy, LocalDate roundsBy) {
    96	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / LATE_PERIOD_DAYS : 0;
    97	        BigDecimal pct = settings.latePct(date);
    98	        return RateService.due(figure.multiply(BigDecimal.valueOf(periods)), pct, rounding(roundsBy));
    99	    }
   100	}
