    25	    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, ApplicationEventPublisher events) {
    26	        this.rollup = rollup;
    27	        this.rates = rates;
    28	        this.sheets = sheets;
    29	        this.events = events;
    30	    }
    31	
    32	    /** The sheet's rates by grade, each grade's earliest first (one with no from-date before all). */
    33	    @Transactional(readOnly = true)
    34	    public List<Rate> list(String sheetId) {
    35	        return rates.findBySheetId(sheetId).stream()
    36	                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate::getFromDate,
    37	                        Comparator.nullsFirst(Comparator.naturalOrder())))
    38	                .toList();
    39	    }
    40	
    41	    /** The sheet's rates with its today, dated settings and policy date, to find the rate in force and the live due on any date. */
    42	    @Transactional(readOnly = true)
    43	    public RateTable table(String sheetId) {
    44	        return new RateTable(list(sheetId), sheets.today(sheetId), sheets.settings(sheetId),
    45	                sheets.policyDate(sheetId));
    46	    }
    47	
    48	    /**
    49	     * Set a grade's rate from a from-date (null: from the beginning of time) through a to-date (null: no
    50	     * end), replacing the one it had from that date.
    51	     */
    52	    @Transactional
    53	    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
    54	        sheets.load(sheetId, user);
    55	        BigDecimal scaled = pct.setScale(2, RoundingMode.HALF_UP);
    56	        Rollup.Figures before = rollup.figures(sheetId);
    57	        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from).orElse(null);
    58	        if (rate == null) {
    59	            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, scaled));
    60	        } else {
    61	            rate.setPct(scaled);
    62	            rate.setToDate(to);
    63	            rates.flush();
    64	        }
    65	        events.publishEvent(new RateChanged(sheetId, user, grade, scaled, from, to));
    66	        rollup.changed(sheetId, user, before);
    67	        return rate;
    68	    }
    69	
    70	    /** An amount times a percent, divided by 100, rounded as given to two decimals; null with no rate. */
    71	    public static BigDecimal due(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
    72	        return pct == null ? null : amount.multiply(pct).divide(HUNDRED).setScale(2, rounding);
    73	    }
    74	}
