    29	    public Sheet load(String id, String user) {
    30	        try {
    31	            return loadOrCreate(id, user);
    32	        } catch (DataIntegrityViolationException e) {
    33	            // Another user started the same sheet at the same moment: theirs is the one.
    34	            return sheets.findById(id).orElseThrow(() -> e);
    35	        }
    36	    }
