    59	     * The next claim number on the sheet: 1 for the first, then 2, and so on. Two users taking one
    60	     * at the same moment wait on each other, so no number is given twice or skipped.
    61	     */
    62	    @Transactional
    63	    public int nextClaimNumber(String id) {
    64	        if (sheets.bumpClaimNumber(id) != 1) {
