    10	 * A sheet's dated settings: the value of each in force on a date is the one with the latest from-date on
    11	 * or before it (a value with no from-date applying from the beginning of time); before every from-date,
    12	 * and where that value was saved blank, the sheet's starting value (1.00 for the floor, 0.00 for the late
    13	 * percent, 14 days for the terms; none for the clerk limit and the cap; the sheet's terms for a grade's own
    14	 * terms).
    15	 */
    16	public record DatedSettings(List<SheetSetting> values) {
    17	
    18	    public static final String CLERK_LIMIT = "clerk-limit";
    19	
    20	    public static final String FLOOR = "floor";
    21	
    22	    public static final String TERMS = "terms";
    23	
    24	    public static final String LATE_PCT = "late-pct";
    25	
    26	    public static final String CAP = "cap";
    27	
    28	    /** A sheet with no value saved: every setting has its starting value on every date. */
    29	    public static final DatedSettings NONE = new DatedSettings(List.of());
    30	
    31	    /** The key of a grade's own terms: terms-A, terms-B or terms-C. */
    32	    public static String gradeTermsKey(String grade) {
    33	        return TERMS + "-" + grade;
    34	    }
    35	
    36	    /** The key's value in force on the date as written; empty when none is (or it was saved blank). */
    37	    public Optional<String> on(String key, LocalDate date) {
    38	        return values.stream()
    39	                .filter(v -> v.getKey().equals(key))
    40	                .filter(v -> v.getFromDate() == null || !v.getFromDate().isAfter(date))
    41	                .max(Comparator.comparing(SheetSetting::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
    42	                .map(SheetSetting::getValue);
    43	    }
    44	
    45	    /** The least live due a claim dated on the date has. */
    46	    public BigDecimal floor(LocalDate date) {
    47	        return on(FLOOR, date).map(BigDecimal::new).orElse(Sheet.DEFAULT_FLOOR);
    48	    }
    49	
    50	    /** The percent an overdue claim dated on the date gains of its figure for every full 30 days. */
    51	    public BigDecimal latePct(LocalDate date) {
    52	        return on(LATE_PCT, date).map(BigDecimal::new).orElse(Sheet.DEFAULT_LATE_PCT);
