    10	/**
    11	 * Loads a sheet by id, starting an empty one when the id was never used, and keeps the sheet's
    12	 * today. The real clock is read only to start a new sheet's today; everything else that depends
    13	 * on the date asks {@link #today(String)}.
    14	 */
    15	@Service
    16	public class SheetService {
    17	
    18	    private final SheetRepository sheets;
    19	    private final SheetSettingRepository settings;
    20	    private final Rollup rollup;
    21	    private final Clock clock = Clock.systemDefaultZone();
    22	
    23	    public SheetService(SheetRepository sheets, SheetSettingRepository settings, Rollup rollup) {
    24	        this.sheets = sheets;
    25	        this.settings = settings;
    26	        this.rollup = rollup;
    27	    }
    28	
    29	    public Sheet load(String id, String user) {
    30	        try {
    31	            return loadOrCreate(id, user);
    32	        } catch (DataIntegrityViolationException e) {
    33	            // Another user started the same sheet at the same moment: theirs is the one.
    34	            return sheets.findById(id).orElseThrow(() -> e);
    35	        }
    36	    }
    37	
    38	    /** The sheet's dated settings: the floor, late percent, terms, clerk limit and cap in force on any date. */
    39	    public DatedSettings settings(String id) {
    40	        return new DatedSettings(settings.findBySheetId(id));
    41	    }
    42	
    43	    /** The sheet's policy date as set; null when blank (the sheet's today is the policy date then). */
    44	    public LocalDate policyDate(String id) {
    45	        return sheets.findById(id).map(Sheet::getPolicyDate).orElse(null);
    46	    }
    47	
    48	    /** The sheet's period numbering from as set; null when blank (off). */
    49	    public LocalDate periodNumberingFrom(String id) {
    50	        return sheets.findById(id).map(Sheet::getPeriodNumberingFrom).orElse(null);
    51	    }
    52	
    53	    /** The sheet's today: the date to use for every decision and default date on the sheet. */
    54	    public LocalDate today(String id) {
    55	        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
    56	    }
    57	
    58	    /**
    59	     * The next claim number on the sheet: 1 for the first, then 2, and so on. Two users taking one
    60	     * at the same moment wait on each other, so no number is given twice or skipped.
    61	     */
    62	    @Transactional
    63	    public int nextClaimNumber(String id) {
    64	        if (sheets.bumpClaimNumber(id) != 1) {
    65	            throw new IllegalStateException("No such sheet " + id);
    66	        }
    67	        return sheets.lastClaimNumber(id);
    68	    }
