    70	    /**
    71	     * Change the sheet's today, starting the sheet if it was never loaded. The change has no audit
    72	     * line of its own, only the figures it moves.
    73	     */
    74	    @Transactional
    75	    public Sheet setToday(String id, String user, LocalDate today) {
    76	        Sheet sheet = load(id, user);
    77	        Rollup.Figures before = rollup.figures(id);
    78	        sheet.setToday(today);
    79	        Sheet saved = sheets.saveAndFlush(sheet);
    80	        rollup.changed(id, user, before);
    81	        return saved;
    82	    }
