    62	    /** Take a statement for the person as of the sheet's today. */
    63	    @Transactional
    64	    public void take(String sheetId, String user, long personId) {
    65	        Person person = people.findByIdAndSheetId(personId, sheetId)
    66	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    67	        Rollup.Figures before = rollup.figures(sheetId);
    68	        RateTable table = rates.table(sheetId);
    69	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
    70	        BigDecimal dueTotal = Dues.total(person::gradeOn, theirs, table, person::heldOn);
    71	        int counting = 0;
    72	        for (Claim claim : theirs) {
    73	            if (Dues.counts(claim, person::heldOn, table.today())) {
    74	                claim.bind(Dues.base(claim, person::gradeOn, table));
    75	                counting++;
