    78	            }
    79	        }
    80	        claims.flush();
    81	        statements.saveAndFlush(new Statement(sheetId, personId, sheets.today(sheetId), dueTotal, counting));
    82	        events.publishEvent(new StatementTaken(sheetId, user, person.getName(), dueTotal, counting));
    83	        rollup.changed(sheetId, user, before);
    84	    }
