    71	    /** The sheet's figures now. */
    72	    public Figures figures(String sheetId) {
    73	        Sheet sheet = sheets.findById(sheetId).orElse(null);
    74	        LocalDate today = sheet == null ? LocalDate.now() : sheet.getToday();
    75	        RateTable table = new RateTable(rates.findBySheetId(sheetId), today,
    76	                new DatedSettings(settings.findBySheetId(sheetId)), sheet == null ? null : sheet.getPolicyDate());
    77	        Map<Long, List<Claim>> bySheet = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
    78	                .collect(Collectors.groupingBy(Claim::getPersonId));
    79	        Map<Long, PersonFigures> figures = new LinkedHashMap<>();
    80	        BigDecimal claimedTotal = BigDecimal.ZERO;
    81	        BigDecimal dueTotal = BigDecimal.ZERO;
    82	        BigDecimal overdueTotal = BigDecimal.ZERO;
    83	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
    84	            List<Claim> theirs = bySheet.getOrDefault(person.getId(), List.of());
    85	            BigDecimal claimed = theirs.stream().filter(c -> Dues.counts(c, person::heldOn, today)).map(Claim::getAmount)
    86	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
    87	            BigDecimal due = Dues.total(person::gradeOn, theirs, table, person::heldOn);
    88	            BigDecimal overdue = Dues.sum(person::gradeOn, Dues.overdue(theirs, table, person::heldOn), table);
    89	            claimedTotal = claimedTotal.add(claimed);
    90	            overdueTotal = overdueTotal.add(overdue.setScale(2, RoundingMode.HALF_UP));
    91	            if (due != null) {
    92	                dueTotal = dueTotal.add(due);
    93	            }
    94	            figures.put(person.getId(), new PersonFigures(person.getName(), money(claimed),
    95	                    due == null ? "n/a" : money(due), money(overdue)));
    96	        }
    97	        return new Figures(figures, new Totals(money(claimedTotal), money(dueTotal), money(overdueTotal)));
    98	    }
