   102	     * who did not exist before counting as changed), then the totals when they changed. Nothing when no
   103	     * figure moved.
   104	     */
   105	    public void changed(String sheetId, String user, Figures before) {
   106	        Figures after = figures(sheetId);
   107	        List<PersonFigures> moved = new ArrayList<>();
   108	        after.people().forEach((id, now) -> {
   109	            if (!now.sameFigures(before.people().get(id))) {
   110	                moved.add(now);
   111	            }
   112	        });
   113	        Totals totals = Objects.equals(before.totals(), after.totals()) ? null : after.totals();
   114	        if (!moved.isEmpty() || totals != null) {
   115	            events.publishEvent(new RollupChanged(sheetId, user, moved, totals));
   116	        }
   117	    }
