    62	    /**
    63	     * Add a period from {@code from} to {@code to}, both inclusive. Refused when the name is taken on the
    64	     * sheet, the to-date is before the from-date, or it shares a date with another period. Two users adding
    65	     * one at the same moment wait on each other, so no two overlap.
    66	     */
    67	    @Transactional
    68	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
    69	        sheets.load(sheetId, user);
    70	        sheetRows.lockById(sheetId);
    71	        if (to.isBefore(from)) {
    72	            throw new PeriodRefused("The to-date is before the from-date.");
    73	        }
    74	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
    75	            throw new PeriodRefused("That period name is already in use on this sheet.");
    76	        }
    77	        if (list(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
    78	            throw new PeriodRefused("The period overlaps another period.");
    79	        }
    80	        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to));
    81	        events.publishEvent(new PeriodAdded(sheetId, user, name, from, to));
    82	        return period;
    83	    }
    84	
    85	    /**
    86	     * Close a period, fixing each person's due-total for it, for every person on the sheet, and its own, their sum: the due figures of the claims that count (OPEN, PENDING and SETTLED,
    87	     * but not an unbound OPEN claim dated within a hold of its person) dated inside it, added up per person. Refused when it is already closed. Takes turns with claim changes on the
    88	     * sheet, so the total fixed is the one the claims had at that moment.
    89	     */
    90	    @Transactional
    91	    public Period close(String sheetId, String user, long periodId) {
    92	        sheetRows.lockById(sheetId);
    93	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
    94	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
    95	        if (period.isClosed()) {
    96	            throw new PeriodRefused("The period is already closed.");
    97	        }
    98	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
    99	                .collect(Collectors.toMap(Person::getId, p -> p));
   100	        RateTable table = rates.table(sheetId);
   101	        Map<Long, BigDecimal> totals = new HashMap<>();
   102	        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
   103	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
   104	                .filter(c -> Dues.counts(c, byId.get(c.getPersonId())::heldOn, table.today()) && period.contains(c.getDate()))
   105	                .forEach(c -> {
   106	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
   107	                    if (due != null) {
   108	                        totals.merge(c.getPersonId(), due, BigDecimal::add);
   109	                    }
   110	                });
   111	        totals.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
   112	        period.close(totals);
   113	        BigDecimal total = period.getClosedTotal().setScale(2, RoundingMode.HALF_UP);
   114	        periods.flush();
   115	        events.publishEvent(new PeriodClosed(sheetId, user, period.getName(), total));
   116	        return period;
   117	    }
   118	
   119	    /**
   120	     * Reopen a closed period: its due-total is live again, the current figures of the claims dated inside
   121	     * it. Refused unless the user is a steward on the sheet, and when the period is not closed.
   122	     */
   123	    @Transactional
   124	    public Period reopen(String sheetId, String user, long periodId) {
   125	        sheetRows.lockById(sheetId);
   126	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
   127	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
   128	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
   129	            throw new PeriodRefused("Only a steward can reopen a period.");
   130	        }
   131	        if (!period.isClosed()) {
   132	            throw new PeriodRefused("The period is not closed.");
   133	        }
   134	        period.reopen();
   135	        periods.flush();
   136	        events.publishEvent(new PeriodReopened(sheetId, user, period.getName()));
   137	        return period;
   138	    }
