   140	    /** The closed period whose dates contain the date, if any. */
   141	    @Transactional(readOnly = true)
   142	    public Optional<Period> closedOn(String sheetId, LocalDate date) {
   143	        return list(sheetId).stream().filter(p -> p.isClosed() && p.contains(date)).findFirst();
   144	    }
