   146	    /**
   147	     * Refuse a change to a claim dated on any of the dates when a closed period contains it. Holds the
   148	     * sheet's lock until the transaction ends, so a period cannot close while the change is made.
   149	     */
   150	    @Transactional
   151	    public void requireOpen(String sheetId, LocalDate... dates) {
   152	        sheetRows.lockById(sheetId);
   153	        for (LocalDate date : dates) {
   154	            closedOn(sheetId, date).ifPresent(p -> {
   155	                throw new ClosedPeriodRefused(p.getName());
   156	            });
   157	        }
   158	    }
